import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_ZONA, MODELO_PARQUE, TABLA_ZONAS } from '../../models/parque-zona.model.mjs';

export async function buscarParqueRepository(parqueId) {
  const { Item } = await MODELO_PARQUE.build(GetItemCommand)
    .key({ parqueId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarParqueRepository(parqueId, minimo) {
  const { Items = [] } = await TABLA_ZONAS.build(QueryCommand)
    .entities(MODELO_ZONA)
    .query({ index: 'PorParque', partition: parqueId })
    .options({ filters: { Zona: { attr: 'capacidad', gte: minimo } } })
    .send();
  return Items;
}
